let t0 = performance.now();
function hexToRgb(hex){const n=parseInt(hex.slice(1),16);return [(n>>16)&255,(n>>8)&255,n&255];}
const deepRGB=hexToRgb(PALETTE[0]);
const hazeRGB=hexToRgb(PALETTE[1]);
const warmRGB=hexToRgb(PALETTE[2]);

const dust=[];
for(let i=0;i<70;i++){
  dust.push({a:Math.random()*Math.PI*2,r:0.55+Math.random()*0.65,speed:0.05+Math.random()*0.08,size:1+Math.random()*2.4,phase:Math.random()*Math.PI*2,pulseSpeed:0.3+Math.random()*0.5});
}

const pollen=[];
for(let i=0;i<40;i++){
  pollen.push({x:Math.random(),y:Math.random(),size:0.6+Math.random()*1.8,driftX:(Math.random()-0.5)*0.00012,driftY:-0.00008-Math.random()*0.00012,phase:Math.random()*Math.PI*2});
}

const droplets=[];
const dropCount=4;
for(let i=0;i<dropCount;i++){
  droplets.push({t:i/dropCount,speed:0.00016+Math.random()*0.00006,size:5+Math.random()*4,trail:[]});
}

function draw(now){
  const dt=now-t0; t0=now;
  const w=W(), h=H();
  ctx.clearRect(0,0,w,h);
  const cx=w*0.21, cy=h*0.76;
  const R=Math.min(w,h)*0.165;
  const time=now*0.001;

  ctx.save();
  ctx.translate(cx, cy-R*0.95);
  ctx.rotate(-0.25);
  ctx.strokeStyle='rgba('+deepRGB.join(',')+',0.55)';
  ctx.lineWidth=Math.max(2,R*0.045);
  ctx.lineCap='round';
  ctx.beginPath();
  ctx.moveTo(0,0);
  ctx.quadraticCurveTo(R*0.15,-R*0.35,R*0.05,-R*0.62);
  ctx.stroke();
  ctx.fillStyle='rgba('+hazeRGB.join(',')+',0.35)';
  ctx.beginPath();
  ctx.ellipse(R*0.18,-R*0.3,R*0.22,R*0.11,0.6,0,Math.PI*2);
  ctx.fill();
  ctx.restore();

  const grad=ctx.createRadialGradient(cx-R*0.35, cy-R*0.4, R*0.1, cx, cy, R*1.15);
  grad.addColorStop(0,'rgba('+warmRGB.join(',')+',0.55)');
  grad.addColorStop(0.35,'rgba('+deepRGB.join(',')+',0.95)');
  grad.addColorStop(1,'rgba('+deepRGB.map(c=>Math.max(0,c-40)).join(',')+',1)');
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, R, R*1.08, 0, 0, Math.PI*2);
  ctx.fillStyle=grad;
  ctx.fill();

  ctx.strokeStyle='rgba(0,0,0,0.18)';
  ctx.lineWidth=Math.max(1.5, R*0.02);
  ctx.beginPath();
  ctx.moveTo(cx, cy-R*1.0);
  ctx.quadraticCurveTo(cx-R*0.08, cy, cx, cy+R*1.05);
  ctx.stroke();

  ctx.globalCompositeOperation='lighter';
  const hl=ctx.createRadialGradient(cx-R*0.4, cy-R*0.5,0, cx-R*0.4, cy-R*0.5, R*0.5);
  hl.addColorStop(0,'rgba(255,255,255,0.35)');
  hl.addColorStop(1,'rgba(255,255,255,0)');
  ctx.fillStyle=hl;
  ctx.beginPath();
  ctx.ellipse(cx-R*0.4, cy-R*0.5, R*0.5, R*0.4, 0,0,Math.PI*2);
  ctx.fill();
  ctx.globalCompositeOperation='source-over';
  ctx.restore();

  for(const d of dust){
    d.a += d.speed*0.01;
    const rr=R*d.r;
    const px=cx+Math.cos(d.a)*rr;
    const py=cy+Math.sin(d.a)*rr*1.06;
    const pulse=0.25+0.2*Math.sin(time*d.pulseSpeed+d.phase);
    ctx.beginPath();
    ctx.fillStyle='rgba('+hazeRGB.join(',')+','+pulse.toFixed(3)+')';
    ctx.arc(px,py,d.size,0,Math.PI*2);
    ctx.fill();
  }

  for(const dr of droplets){
    dr.t += dr.speed*dt;
    if(dr.t>1){ dr.t-=1; dr.trail=[]; }
    const startX=cx+R*0.55, startY=cy-R*0.2;
    const endX=w*0.78, endY=h*0.18;
    const ease=dr.t;
    const px=startX+(endX-startX)*ease;
    const py=startY+(endY-startY)*ease - Math.sin(ease*Math.PI)*h*0.06;
    dr.trail.push({x:px,y:py});
    if(dr.trail.length>14) dr.trail.shift();
    for(let i=0;i<dr.trail.length;i++){
      const pnt=dr.trail[i];
      const alpha=(i/dr.trail.length)*0.4;
      ctx.beginPath();
      ctx.fillStyle='rgba('+warmRGB.join(',')+','+alpha.toFixed(3)+')';
      ctx.arc(pnt.x,pnt.y,dr.size*(i/dr.trail.length),0,Math.PI*2);
      ctx.fill();
    }
    ctx.save();
    ctx.shadowColor='rgba('+deepRGB.join(',')+',0.6)';
    ctx.shadowBlur=8;
    ctx.beginPath();
    ctx.fillStyle='rgba('+deepRGB.join(',')+',0.85)';
    ctx.ellipse(px,py,dr.size*0.8,dr.size,0,0,Math.PI*2);
    ctx.fill();
    ctx.restore();
    ctx.beginPath();
    ctx.fillStyle='rgba(255,255,255,0.5)';
    ctx.arc(px-dr.size*0.25,py-dr.size*0.3,dr.size*0.25,0,Math.PI*2);
    ctx.fill();
  }

  for(const p of pollen){
    p.x += p.driftX*dt;
    p.y += p.driftY*dt;
    if(p.y<-0.05) p.y=1.05;
    if(p.x<-0.05) p.x=1.05;
    if(p.x>1.05) p.x=-0.05;
    const px=p.x*w, py=p.y*h;
    const distToCenter=Math.hypot(px-w*0.5, py-h*0.5);
    const maxFade=Math.min(w,h)*0.3;
    const fade=distToCenter<maxFade ? distToCenter/maxFade : 1;
    const glow=0.25+0.15*Math.sin(time*0.6+p.phase);
    ctx.beginPath();
    ctx.fillStyle='rgba('+warmRGB.join(',')+','+(glow*fade*0.6).toFixed(3)+')';
    ctx.arc(px,py,p.size,0,Math.PI*2);
    ctx.fill();
  }

  requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
